"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["72251"],{56602(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>d,frontMatter:()=>o,contentTitle:()=>l,toc:()=>h,assets:()=>r});var a=JSON.parse('{"id":"challengemen","title":"","description":"2006/2/19 918","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/challengemen.md","sourceDirName":".","slug":"/challengemen","permalink":"/en/challengemen","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"challengemen","title":"","hide_table_of_contents":true,"sidebar_label":"Challenging All Men in the World \u2014 If This Lady Loses, She Quits the Internet Immediately! (2006/2/19 9:11:18)"},"sidebar":"timelineSidebar","previous":{"title":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n: Chan Is Not Chan, Zen Is Not Zen, Dead Wood Dragon Chant Illuminates the Universe (18) (2006/2/17 8:06:54)","permalink":"/en/timeline/zen/18"},"next":{"title":"Serial 1: Men I\'ve \\"Slept With\\" or \\"Consumed\\"! (2006/2/20 10:04:35)","permalink":"/en/timeline/music/menconsumed1"}}'),s=t(74848),i=t(28453);let o={id:"challengemen",title:"",hide_table_of_contents:!0,sidebar_label:"Challenging All Men in the World \u2014 If This Lady Loses, She Quits the Internet Immediately! (2006/2/19 9:11:18)"},l="Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!",r={},h=[{value:"Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!",id:"challenging-all-men-in-the-world----if-i-lose-i-quit-the-internet-immediately-1",level:3},{value:"Replies",id:"replies",level:3}];function c(e){let n={a:"a",blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"challenging-all-men-in-the-world----if-i-lose-i-quit-the-internet-immediately",children:"Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!"})}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:"2006/2/19 9:11:18"}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"challenging-all-men-in-the-world----if-i-lose-i-quit-the-internet-immediately-1",children:"Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!"}),"\n",(0,s.jsxs)(n.p,{children:["A Girl Who Loves Mathematics",(0,s.jsx)("br",{}),"\nCh\xe1n Zh\u014Dng Shu\u014D Ch\xe1n ",(0,s.jsx)(n.a,{href:"http://blog.sina.com.cn/m/chzhshch",children:"http://blog.sina.com.cn/m/chzhshch"})]}),"\n",(0,s.jsx)(n.p,{children:"I have never met my match online. I've made men in the most popular corners of the Chinese internet thoroughly uncomfortable. Truth be told, I'm quite uncomfortable too -- how is it that there isn't a single formidable opponent in this world who could make me break a sweat? I know the men online resent me, concocting petty schemes left and right to prove the narrow-mindedness of the male heart. Fine. Today I'm giving all the men in the world a chance. I won't even pose a particularly difficult challenge -- just compose a ci poem matching the rhyme scheme of one I dashed off casually. If even a single one surpasses mine, I'll quit the internet immediately. This poem isn't even among my best, but it's more than enough to defeat men. Furthermore, I'll give men an extra handicap: if anyone can improve it by changing even a single character, I'll admit defeat and quit the internet for at least half a year. Men, stop being all mouth and bluster. If you want me gone, show me what you've got!"}),"\n",(0,s.jsxs)(n.p,{children:['\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0New residence completed, New Year approaching -- a casual "Linjiang Xian" to mark the occasion.',(0,s.jsx)("br",{}),'\n\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Note: "New residence completed" refers to the launch of my blog Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n ',(0,s.jsx)(n.a,{href:"http://blog.sina.com.cn/m/chzhshch",children:"http://blog.sina.com.cn/m/chzhshch"})]}),"\n",(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Turbid waters tilt in waves for thirty thousand li; solemn, I sit alone on a solitary peak. The dragon lies hidden, the lion asleep, awaiting the gale. The heartless are all mere upstarts; those with tears are heroes too."}),"\n",(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0A long sword leans against heaven, where stars and constellations blaze; past and present pass before the eyes into emptiness. Heaven and earth, looked up to and down upon, are left to fortune and hardship. Half a moon hangs above the blue sea; a single reed-skiff heads east on the great river."}),"\n",(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0All men of the world, it's your move!"}),"\n",(0,s.jsx)(n.h3,{id:"replies",children:"Replies"}),"\n",(0,s.jsxs)("div",{class:"blog-comment",children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/2/19 15:43:00",(0,s.jsx)("br",{})]}),(0,s.jsx)(n.p,{children:'A Poetry Lesson for Foolish Men, Regarding Responses to My "Challenge All Men" Post'}),(0,s.jsxs)(n.p,{children:["\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0A Girl Who Loves Mathematics ",(0,s.jsx)(n.a,{href:"http://blog.sina.com.cn/m/chzhshch",children:"http://blog.sina.com.cn/m/chzhshch"})]}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0My post \"Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!\" has been circulating widely across major websites for three days now. Sadly, not a single person has been able to challenge me. What's even more laughable is that replies are as numerous as ox hairs, yet 99.99999% don't even have basic knowledge of classical poetry. The decline of traditional culture is truly heartbreaking!"}),(0,s.jsx)(n.p,{children:'\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0First, I\'ve seen virtually no one who can even understand the meaning of my ci poem, let alone the basic literary allusions and textual background. The simplest example is the character "zhuo" (turbid) in the first line "Turbid waters tilt in waves for thirty thousand li" -- why this character and not another? The title of this poem is "Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n." In Buddhism, there are the "five turbidities" (wu zhuo), and that\'s where it comes from. In fine poetry, every character must have its provenance. It needn\'t be in the manner of the Jiangxi School, but every character must have its root and must relate to the theme. Otherwise, it\'s a superfluous character. Whether a poem reaches a certain level of artistic achievement depends most fundamentally on having as few superfluous characters as possible -- ideally none at all. The reason I dare say not a single character can be changed is precisely this.'}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Furthermore, ci is a regulated-verse form and must follow tonal patterns. Some respondents don't even understand the basic tonal rules and just hack away blindly, accomplishing nothing but embarrassing themselves. Men trying to win by numbers and volume is useless. On this kind of matter, I'll say a word or two when I have time, but generally I don't bother. Those who understand will understand. As for those whose writing reads like slogans, that's a matter of basic artistic literacy, and I won't even address it."}),(0,s.jsx)(n.p,{children:'\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Then there\'s the question of literary allusions, which is more complex -- essentially a matter of rhetorical significance. For example, the "yi wei" (a single reed) used in the poem: since the title is "Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n," anyone with a bit of knowledge would know this alludes to Bodhidharma\'s crossing. Bodhidharma of course used a raft or small boat to cross the river. "Yi wei" represents a small boat or raft. "Wei" refers to a reed, and also a reed leaf, metaphorically a small boat -- this usage already appears in the Book of Songs. This kind of rhetorical device is actually quite common. Just as we say "yi ye qing zhou" (a single-leaf light boat), in a poetic line you can simply use "yi ye" (a single leaf). Poetry demands conciseness. Only foolish men would take "yi ye" to mean a single tree leaf!'}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0In short, learning is something that can't be faked. If you lack learning, that's fine -- go home and study, foolish men!"})]}),"\n",(0,s.jsxs)("div",{class:"blog-comment",children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/2/19 15:46:36",(0,s.jsx)("br",{})]}),(0,s.jsx)(n.p,{children:'A Poetry Lesson for Foolish Men, Regarding Responses to My "Challenge All Men" Post'}),(0,s.jsxs)(n.p,{children:["\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0A Girl Who Loves Mathematics ",(0,s.jsx)(n.a,{href:"http://blog.sina.com.cn/m/chzhshch",children:"http://blog.sina.com.cn/m/chzhshch"})]}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0My post \"Challenging All Men in the World -- If I Lose, I Quit the Internet Immediately!\" has been circulating widely across major websites for three days now. Sadly, not a single person has been able to challenge me. What's even more laughable is that replies are as numerous as ox hairs, yet 99.99999% don't even have basic knowledge of classical poetry. The decline of traditional culture is truly heartbreaking!"}),(0,s.jsx)(n.p,{children:'\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0First, I\'ve seen virtually no one who can even understand the meaning of my ci poem, let alone the basic literary allusions and textual background. The simplest example is the character "zhuo" (turbid) in the first line "Turbid waters tilt in waves for thirty thousand li" -- why this character and not another? The title of this poem is "Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n." In Buddhism, there are the "five turbidities" (wu zhuo), and that\'s where it comes from. In fine poetry, every character must have its provenance. It needn\'t be in the manner of the Jiangxi School, but every character must have its root and must relate to the theme. Otherwise, it\'s a superfluous character. Whether a poem reaches a certain level of artistic achievement depends most fundamentally on having as few superfluous characters as possible -- ideally none at all. The reason I dare say not a single character can be changed is precisely this.'}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Furthermore, ci is a regulated-verse form and must follow tonal patterns. Some respondents don't even understand the basic tonal rules and just hack away blindly, accomplishing nothing but embarrassing themselves. Men trying to win by numbers and volume is useless. On this kind of matter, I'll say a word or two when I have time, but generally I don't bother. Those who understand will understand. As for those whose writing reads like slogans, that's a matter of basic artistic literacy, and I won't even address it."}),(0,s.jsx)(n.p,{children:'\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0Then there\'s the question of literary allusions, which is more complex -- essentially a matter of rhetorical significance. For example, the "yi wei" (a single reed) used in the poem: since the title is "Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n," anyone with a bit of knowledge would know this alludes to Bodhidharma\'s crossing. Bodhidharma of course used a raft or small boat to cross the river. "Yi wei" represents a small boat or raft. "Wei" refers to a reed, and also a reed leaf, metaphorically a small boat -- this usage already appears in the Book of Songs. This kind of rhetorical device is actually quite common. Just as we say "yi ye qing zhou" (a single-leaf light boat), in a poetic line you can simply use "yi ye" (a single leaf). Poetry demands conciseness. Only foolish men would take "yi ye" to mean a single tree leaf!'}),(0,s.jsx)(n.p,{children:"\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0In short, learning is something that can't be faked. If you lack learning, that's fine -- go home and study, foolish men!"})]})]})}function d(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>o,x:()=>l});var a=t(96540);let s={},i=a.createContext(s);function o(e){let n=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);